{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Brexpiprazole, the closest structural analogue sharing the 3,4-dihydroquinolin-2-one core and butoxy-N-arylpiperazine linker, has an absolute oral bioavailability of 95% in humans, strongly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Ziprasidone, another aryl-piperazine antipsychotic, has an absolute oral bioavailability of 59% in healthy men, which is well above the 20% threshold and supports a high-F classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Urapidil, a piperazine-containing drug with moderate first-pass metabolism, shows 78% absolute oral bioavailability, providing additional support that this structural class can achieve high oral exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is aripiprazole, a 3,4-dihydroquinolin-2-one with a butoxy-N-arylpiperazine side chain. The closest analogue brexpiprazole has 95% absolute oral bioavailability in humans, and other related piperazine antipsychotics also show F values well above 20%. The low-bioavailability examples are structurally distant and do not outweigh the strong transferable evidence for high bioavailability.",
  "evidence_gaps": [
    "No direct experimental record for aripiprazole itself is present in the supplied evidence; the prediction relies on close structural analogues.",
    "Quantitative transfer from brexpiprazole is strong but not exact, and differences in metabolic stability or transporter interactions could modestly alter the absolute F value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

